	public Session open(RowState row, NativeKeyedSubqueryJoinPlan plan) {
		NativeExecutionContext execution = sub.executionContextOf(row);
		Index index = NativeSubqueryPlan.attemptScopedState(execution, new IndexKey(sub),
				() -> Index.build(row, sub, plan, execution));
		return new IndexSession(index, plan.payloadSlots);
	}

